#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Buffs;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Detections;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Contraptions;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine;
using PVZEngine.Auras;
using PVZEngine.Buffs;
using PVZEngine.Collisions;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Grids;
using PVZEngine.Models;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.autotrap)]
    public class Autotrap : AIEntityBehaviour
    {
        public Autotrap(string nsp, string name) : base(nsp, name)
        {
            AddAura(new TrappedAura());
        }
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            switch (entity.State)
            {
                case STATE_OPEN:
                    UpdateOpen(entity);
                    break;
                case STATE_CLOSING:
                    UpdateClosing(entity);
                    break;
                case STATE_CLOSED:
                    UpdateClosed(entity);
                    break;
                case STATE_OPENING:
                    UpdateOpening(entity);
                    break;
            }
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            entity.SetAnimationBool("Closed", IsClosing(entity) || IsClosed(entity));
            entity.SetModelProperty("Evoked", entity.IsEvoked());
        }
        public override void PostCollision(EntityCollision collision, int state)
        {
            base.PostCollision(collision, state);
            if (state == EntityCollisionHelper.STATE_EXIT)
                return;
            if (!collision.Collider.IsForMain())
                return;
            var trap = collision.Entity;
            if (!CanClose(trap))
                return;
            var other = collision.Other;
            if (!IsValidTarget(trap, other) || !Detection.CanDetect(other))
                return;
            StartClosing(trap);
        }
        private static void UpdateOpen(Entity trap)
        {

        }
        private static void UpdateClosing(Entity trap)
        {
            var stateTimer = GetOrCreateStateTimer(trap);
            if (stateTimer.RunToExpired())
            {
                StartClosed(trap);
            }
        }
        private static void UpdateClosed(Entity trap)
        {
            var target = trap.Target;
            var stateTimer = GetOrCreateStateTimer(trap);
            if (stateTimer.RunToExpired())
            {
                if (!target.ExistsAndAlive() || !IsValidTarget(trap, target))
                {
                    StartOpening(trap);
                }
                else
                {
                    var damage = trap.GetDamage() * GetContinuousDamageMultiplier(trap);
                    TrapDamage(trap, target, damage);
                    ShakeTrap(trap);
                    stateTimer.Reset();
                }
            }
            if (target.ExistsAndAlive())
            {
                target.Position = Ticks.SmoothDamp(target.Position, trap.Position, 0.9f);
                target.Velocity = Vector3.zero;
            }
        }
        private static void UpdateOpening(Entity trap)
        {
            var stateTimer = GetOrCreateStateTimer(trap);
            if (stateTimer.RunToExpired())
            {
                StartOpen(trap);
            }
        }
        public static void StartClosing(Entity trap)
        {
            trap.State = STATE_CLOSING;
            var stateTimer = GetOrCreateStateTimer(trap);
            stateTimer.ResetTime(CLOSING_FRAMES);
            trap.PlaySound(VanillaSoundID.trapClose);
        }
        public static void StartClosed(Entity trap)
        {
            trap.Target = FindTrapTarget(trap);
            if (trap.Target.ExistsAndAlive())
            {
                if (trap.IsEvoked())
                {
                    Instakill(trap, trap.Target);
                    ChargedExplode(trap);
                    trap.SetEvoked(false);
                }
                else
                {
                    var damage = trap.GetDamage() * GetTrappedDamageMultiplier(trap);
                    TrapDamage(trap, trap.Target, damage);
                }
            }
            trap.State = STATE_CLOSED;

            var stateTimer = GetOrCreateStateTimer(trap);
            stateTimer.ResetSeconds(GetTrappedDamageInterval(trap));
        }
        public static void StartOpening(Entity trap)
        {
            trap.State = STATE_OPENING;
            trap.Target = null;
            var stateTimer = GetOrCreateStateTimer(trap);
            stateTimer.ResetTime(OPENING_FRAMES);
            trap.PlaySound(VanillaSoundID.trapOpen);
        }
        public static void StartOpen(Entity trap)
        {
            trap.State = STATE_OPEN;
        }
        public static bool CanClose(Entity trap)
        {
            return IsOpen(trap) && !trap.IsAIFrozen();
        }
        public static bool IsValidTarget(Entity trap, Entity target)
        {
            return target.Type == EntityTypes.ENEMY && !target.IsDead && trap.IsHostile(target);
        }
        public static bool IsOpen(Entity trap)
        {
            return trap.State == STATE_OPEN;
        }
        public static bool IsClosing(Entity trap)
        {
            return trap.State == STATE_CLOSING;
        }
        public static bool IsClosed(Entity trap)
        {
            return trap.State == STATE_CLOSED;
        }
        public static bool IsOpening(Entity trap)
        {
            return trap.State == STATE_OPENING;
        }
        public static void TrapDamage(Entity trap, Entity target, float damage)
        {
            target.TakeDamage(damage, new DamageEffectList(VanillaDamageEffects.SLICE), trap);
        }
        public static void Instakill(Entity trap, Entity target)
        {
            var effects = new DamageEffectList(VanillaDamageEffects.INSTA_KILL, VanillaDamageEffects.REMOVE_ON_DEATH, VanillaDamageEffects.NO_DEATH_EFFECTS);
            target.Die(effects, trap);
            trap.Level.ShakeScreen(10, 0, 15);
            Explosion.Spawn(trap, trap.GetCenter(), 40);
            trap.PlaySound(VanillaSoundID.explosion);
        }
        public static void ChargedExplode(Entity trap)
        {
            var radius = trap.GetRange();
            var damage = trap.GetDamage() * GetEvokedDamageMultiplier(trap);
            var effects = new DamageEffectList(VanillaDamageEffects.LIGHTNING, VanillaDamageEffects.DAMAGE_BODY_AFTER_ARMOR_BROKEN, VanillaDamageEffects.STUNS_FRANKENSTEIN);
            TNT.ExplodeArcs(trap, trap.GetCenter(), radius);
            TNT.ChargedExplode(trap, damage, radius);
            trap.PlaySound(VanillaSoundID.thunder);
        }
        public static void ShakeTrap(Entity trap)
        {
            trap.TriggerAnimation("ShakeTrigger");
        }
        public static Entity? FindTrapTarget(Entity trap)
        {
            return trapDetector.Detect(trap)?.Entity;
        }
        public static FrameTimer GetOrCreateStateTimer(Entity entity)
        {
            var stateTimer = GetStateTimer(entity);
            if (stateTimer == null)
            {
                stateTimer = new FrameTimer();
                SetStateTimer(entity, stateTimer);
            }
            return stateTimer;
        }
        public static FrameTimer? GetStateTimer(Entity entity) => entity.GetBehaviourField<FrameTimer>(PROP_STATE_TIMER);
        public static void SetStateTimer(Entity entity, FrameTimer timer) => entity.SetBehaviourField(PROP_STATE_TIMER, timer);
        public static float GetContinuousDamageMultiplier(Entity entity) => entity.GetBehaviourField<float>(PROP_CONTINUOUS_DAMAGE_MULTIPLIER);
        public static void SetContinuousDamageMultiplier(Entity entity, float value) => entity.SetBehaviourField(PROP_CONTINUOUS_DAMAGE_MULTIPLIER, value);
        public static float GetTrappedDamageMultiplier(Entity entity) => entity.GetBehaviourField<float>(PROP_TRAPPED_DAMAGE_MULTIPLIER);
        public static void SetTrappedDamageMultiplier(Entity entity, float value) => entity.SetBehaviourField(PROP_TRAPPED_DAMAGE_MULTIPLIER, value);
        public static float GetTrappedDamageInterval(Entity entity) => entity.GetBehaviourField<float>(PROP_TRAPPED_DAMAGE_INTERVAL);
        public static void SetTrappedDamageInterval(Entity entity, float value) => entity.SetBehaviourField(PROP_TRAPPED_DAMAGE_INTERVAL, value);
        public static float GetEvokedDamageMultiplier(Entity entity) => entity.GetBehaviourField<float>(PROP_EVOKED_DAMAGE_MULTIPLIER);
        public static void SetEvokedDamageMultiplier(Entity entity, float value) => entity.SetBehaviourField(PROP_EVOKED_DAMAGE_MULTIPLIER, value);
        public static readonly VanillaEntityPropertyMeta<FrameTimer> PROP_STATE_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("state_timer");
        public static readonly VanillaEntityPropertyMeta<float> PROP_CONTINUOUS_DAMAGE_MULTIPLIER = new VanillaEntityPropertyMeta<float>("continuous_damage_multiplier", 0.2f);
        public static readonly VanillaEntityPropertyMeta<float> PROP_TRAPPED_DAMAGE_MULTIPLIER = new VanillaEntityPropertyMeta<float>("trapped_damage_multiplier", 0.8f);
        public static readonly VanillaEntityPropertyMeta<float> PROP_TRAPPED_DAMAGE_INTERVAL = new VanillaEntityPropertyMeta<float>("trapped_damage_interval", 0.5f);
        public static readonly VanillaEntityPropertyMeta<float> PROP_EVOKED_DAMAGE_MULTIPLIER = new VanillaEntityPropertyMeta<float>("evoked_damage_multiplier", 18f);

        public static Detector trapDetector = new AutotrapDetector(true);
        public const int CLOSING_FRAMES = 2;
        public const int OPENING_FRAMES = 2;
        public const int STATE_OPEN = VanillaContraptionStates.AUTOTRAP_OPEN;
        public const int STATE_CLOSING = VanillaContraptionStates.AUTOTRAP_CLOSING;
        public const int STATE_CLOSED = VanillaContraptionStates.AUTOTRAP_CLOSED;
        public const int STATE_OPENING = VanillaContraptionStates.AUTOTRAP_OPENING;

        private static List<IEntityCollider> detectBuffer = new List<IEntityCollider>();
        private static HashSet<LawnGrid> gridDetectBuffer = new HashSet<LawnGrid>();
        public class TrappedAura : AuraEffectDefinition
        {
            public TrappedAura() : base(VanillaBuffID.Enemy.trapped)
            {
            }
            public override void GetAuraTargets(AuraEffect auraEffect, List<IBuffTarget> results)
            {
                var sourceEntity = auraEffect.Source.GetEntity();
                if (sourceEntity == null)
                    return;
                if (!sourceEntity.Target.ExistsAndAlive())
                    return;
                results.Add(sourceEntity.Target);
            }
        }
    }
}
